import{HookNotFoundError}from"#compiled/@workflow/errors/index.js";import{resumeHook}from"#internal/workflow/runtime.js";async function forwardTurnCancellationStep(n){"use step";for(let r=0;r<50;r+=1)try{return await resumeHook(n.token,n.payload),!0}catch(t){if(!HookNotFoundError.is(t))throw t;if(r===49)return!1;await new Promise(e=>setTimeout(e,20))}return!1}export{forwardTurnCancellationStep};